            for y, x in comp:
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in visited and grid[yy][xx] == color:
                        visited.add((yy, xx))
                        comp.append((yy, xx))

            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            outside, stack = set(), []
            for y in range(r0, r1+1):
                for x in (c0, c1):
                    if grid[y][x] == bg: stack.append((y,x))
            for x in range(c0, c1+1):
                for y in (r0, r1):
                    if grid[y][x] == bg: stack.append((y,x))
            while stack:
                y, x = stack.pop()
                if (y,x) in outside or not (r0 <= y <= r1 and c0 <= x <= c1) or grid[y][x] != bg:
                    continue
                outside.add((y,x))
                stack.extend(((y-1,x),(y+1,x),(y,x-1),(y,x+1)))

            hole = [(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
